<script>(()=>{const nav=document.getElementById('mobile-nav'),left=document.getElementById('mobile-nav-left'),right=document.getElementById('mobile-nav-right');if(!nav||!left||!right)return;const update=()=>{const max=Math.max(0,nav.scrollWidth-nav.clientWidth),pos=nav.scrollLeft;left.classList.toggle('is-available',pos>3);right.classList.toggle('is-available',pos<max-3)};const scroll=d=>nav.scrollBy({left:d*210,behavior:'smooth'});left.addEventListener('click',()=>left.classList.contains('is-available')&&scroll(-1));right.addEventListener('click',()=>right.classList.contains('is-available')&&scroll(1));nav.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);if('ResizeObserver'in window)new ResizeObserver(update).observe(nav);requestAnimationFrame(update)})();</script>@stack('scripts')</body></html>